class PrefixArray {
    private final long[] prefix;
    private final int n;

    PrefixArray(int[] a) {         // a is 1-based: a[0] unused
        n = a.length - 1;
        prefix = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            prefix[i] = prefix[i - 1] + a[i];
        }
    }

    long prefix(int i) {            // O(1)
        return prefix[i];
    }

    void update(int i, int delta) { // O(n): fix every later prefix
        for (int j = i; j <= n; j++) {
            prefix[j] += delta;
        }
    }
}

