class FenwickTree {
    private final long[] bit;
    private final int n;

    FenwickTree(int n) {
        this.n = n;
        this.bit = new long[n + 1];   // 1-based; index 0 unused
    }

    // Build in O(n) from a 1-based array a[1..n].
    FenwickTree(int[] a) {
        this(a.length - 1);
        for (int i = 1; i <= n; i++) {
            bit[i] += a[i];
            int parent = i + (i & -i);
            if (parent <= n) {
                bit[parent] += bit[i];
            }
        }
    }

    void update(int i, long delta) {   // climb: add lowbit
        for (; i <= n; i += i & -i) {
            bit[i] += delta;
        }
    }

    long prefix(int i) {               // descend: strip lowbit
        long sum = 0;
        for (; i > 0; i -= i & -i) {
            sum += bit[i];
        }
        return sum;
    }

    long rangeSum(int l, int r) {
        return prefix(r) - prefix(l - 1);
    }

    public static void main(String[] args) {
        // a[1..6] = 1,3,5,7,9,11
        FenwickTree ft = new FenwickTree(new int[]{0, 1, 3, 5, 7, 9, 11});
        System.out.println(ft.prefix(3));    // 9
        ft.update(2, 7);                     // a[2] -> 10
        System.out.println(ft.prefix(3));    // 16
        System.out.println(ft.rangeSum(2, 4)); // 10+5+7 = 22
    }
}

