class FenwickTree:
    def __init__(self, n: int) -> None:
        self.n = n
        self.bit = [0] * (n + 1)        # 1-based; index 0 unused

    @classmethod
    def from_array(cls, a: list[int]) -> "FenwickTree":
        # a is 1-based: a[0] unused
        ft = cls(len(a) - 1)
        for i in range(1, ft.n + 1):
            ft.bit[i] += a[i]
            parent = i + (i & -i)
            if parent <= ft.n:
                ft.bit[parent] += ft.bit[i]
        return ft

    def update(self, i: int, delta: int) -> None:   # climb: add lowbit
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def prefix(self, i: int) -> int:                # descend: strip lowbit
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def range_sum(self, l: int, r: int) -> int:
        return self.prefix(r) - self.prefix(l - 1)


